<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Employee Job Letter</h1><p>Select a persisted employee and print the appointment record.</p></div></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Employee</label><select class="module-select" name="employee_id" required><option value="">Select Employee</option><?php foreach($employees as$e):?><option value="<?= $e['id'] ?>" <?= ($employee['id']??0)==$e['id']?'selected':'' ?>><?= e($e['employee_no'].' — '.$e['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary">Generate</button></form><?php if($employee):?><section class="module-card"><header class="module-card__header"><div><h2><?= e($institute['name']) ?></h2><p><?= e($institute['address']) ?></p></div><button class="btn btn--primary" type="button" onclick="window.print()">Print</button></header><div class="module-card__body"><h2>Appointment / Job Letter</h2><p>This confirms the appointment of <strong><?= e($employee['name']) ?></strong> as <strong><?= e($employee['role']) ?></strong>, employee number <?= e($employee['employee_no']) ?>, effective <?= e($employee['joining_date']) ?>.</p><p>Monthly salary: <?= number_format((float)$employee['monthly_salary'],2) ?></p><?php if(!empty($rules['employee'])):?><hr><h3>Employee Rules &amp; Regulations</h3><div><?= $rules['employee'] ?></div><?php endif ?></div></section><?php endif ?></div></div></main>
